function evalYogaRoll(u: number, v: number, t: number, L = 14, W = 7): Vec3 {
    const z = (v - 0.5) * W;
    if (t <= 0.0001) return new Vec3((u - 0.5) * L, 0.0, z);

    const rollFraction = t * 0.88;
    const rollStartU = 1.0 - rollFraction;

    if (u <= rollStartU) {
        // Flat sheet on the floor
        return new Vec3((u - 0.5) * L, 0.0, z);
    } else {
        // Spiral roll tangent to the floor
        const s = (u - rollStartU) * L;
        const R_base = 0.55;
        const layerThickness = 0.045;
        const turns = s / (2.0 * Math.PI * R_base);
        const R = R_base + turns * layerThickness;

        const theta = s / R;
        const rollPivotX = (rollStartU - 0.5) * L;

        const x = rollPivotX + R * Math.sin(theta);
        const y = R * (1.0 - Math.cos(theta));
        return new Vec3(x, y, z);
    }
}

function evalBookFold(u: number, v: number, t: number, L = 14, W = 7): Vec3 {
    const z = (v - 0.5) * W;
    const hingeU = 0.5;
    const bendAngle = t * Math.PI; // 0 to 180 degrees
    const R = 0.55;

    if (u <= hingeU) {
        return new Vec3((u - hingeU) * L, 0.0, z);
    } else {
        const distFromHinge = (u - hingeU) * L;
        const arcLength = bendAngle * R;

        if (distFromHinge <= arcLength) {
            // Circular curved spine
            const phi = distFromHinge / R;
            return new Vec3(R * Math.sin(phi), R * (1.0 - Math.cos(phi)), z);
        } else {
            // Tangential straight flap
            const straight = distFromHinge - arcLength;
            const x = R * Math.sin(bendAngle) + straight * Math.cos(bendAngle);
            const y = R * (1.0 - Math.cos(bendAngle)) + straight * Math.sin(bendAngle);
            return new Vec3(x, y, z);
        }
    }
}

function evalAccordion(u: number, v: number, t: number, L = 14, W = 7): Vec3 {
    const z = (v - 0.5) * W;
    const pleats = 4.0;
    const compress = 1.0 - t * 0.65;
    const x = (u - 0.5) * L * compress;

    const wave = Math.sin(u * pleats * Math.PI * 2);
    const sharpWave = Math.sign(wave) * Math.pow(Math.abs(wave), 0.75);
    const y = sharpWave * (t * 2.6);

    return new Vec3(x, y, z);
}

function evalOrigami(u: number, v: number, t: number, L = 14, W = 7): Vec3 {
    const rawX = (u - 0.5) * L;
    const rawZ = (v - 0.5) * W;

    const diagScale = 1.0 / Math.SQRT2;
    const ax = diagScale, az = diagScale;   // Crease axis vector
    const nx = -diagScale, nz = diagScale; // In-plane normal vector

    const p0x = 0.05 * L, p0z = -0.15 * W;
    const dx = rawX - p0x, dz = rawZ - p0z;

    const distN = dx * nx + dz * nz;
    const distA = dx * ax + dz * az;

    if (distN <= 0.0 || t <= 0.001) {
        return new Vec3(rawX, 0.0, rawZ);
    } else {
        const theta = t * Math.PI;
        const r = distN;

        const foldedX = p0x + distA * ax + r * Math.cos(theta) * nx;
        const foldedY = r * Math.sin(theta);
        const foldedZ = p0z + distA * az + r * Math.cos(theta) * nz;

        return new Vec3(foldedX, foldedY, foldedZ);
    }
}
